"""Copilot v2 skills: which skills a run gets, and how the model loads them.

The model sees one catalog line (name and description) per skill and loads a
skill's body with pydantic-ai's built-in ``load_capability`` tool. Nothing
carries over between turns: the prompt is rebuilt from the flattened chat
history, so every turn starts with no skill loaded.
"""

from __future__ import annotations

from collections.abc import Collection, Mapping, Sequence
from types import MappingProxyType

from pydantic_ai import Agent, RunContext
from pydantic_ai.capabilities import Capability
from pydantic_ai.messages import (
    LoadCapabilityCallPart,
    LoadCapabilityReturnPart,
    RetryPromptPart,
)
from pydantic_ai.tools import ToolDefinition

from rasa.builder.copilot.constants import (
    TOOL_LOAD_CAPABILITY,
    TOOL_LOAD_SKILL_REFERENCE,
)
from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext
from rasa.builder.copilot.skill_catalog import (
    CopilotSkill,
    SkillPolicy,
    SkillUseCase,
    get_skill_catalog,
)
from rasa.shared.engine_version import MANTLE_ENGINE_VERSION

# A skill policy picks the skill use cases an agent gets, so different agents
# and/or deployments can ship different skill sets from one catalog. The Copilot
# picks its policy by the project's engine, and only Mantle has one today.
# Future policies could, for example, give a deployment that serves CALM
# projects SkillPolicy(use_cases={CALM, ANALYTICS}), or give an analytics agent
# SkillPolicy(use_cases={ANALYTICS}).
COPILOT_SKILL_POLICIES: Mapping[str, SkillPolicy] = MappingProxyType(
    {MANTLE_ENGINE_VERSION: SkillPolicy(use_cases=frozenset({SkillUseCase.MANTLE}))}
)

_LOAD_SKILL_REFERENCE_DESCRIPTION = (
    "Read one reference file of a Copilot skill you loaded this turn or were "
    "given in your instructions. Pass the "
    "skill name and the reference path exactly as the skill gives it, for "
    "example 'references/control-ladder.md'."
)


def select_skills(engine: str) -> tuple[CopilotSkill, ...]:
    """Return the packaged skills the Copilot gets for a project on *engine*.

    An engine without a policy gets no skills, so its runs see neither a skill
    catalog nor the ``load_capability`` tool.
    """
    policy = COPILOT_SKILL_POLICIES.get(engine)
    if policy is None:
        return ()
    return get_skill_catalog().for_policy(policy)


def skill_capabilities(
    skills: Sequence[CopilotSkill], *, defer_loading: bool = True
) -> list[Capability[CopilotRunContext]]:
    """Wrap each skill as a capability named after the skill.

    By default the capability is deferred: the model loads it by passing the
    skill name to ``load_capability``, which returns the skill body as the tool
    result. With ``defer_loading=False`` the body is part of the instructions
    from the start, for an agent whose task always needs the skill.
    """
    return [
        Capability(
            id=skill.name,
            description=skill.description,
            instructions=skill.body,
            defer_loading=defer_loading,
        )
        for skill in skills
    ]


def is_skill_load_part(part: object) -> bool:
    """Return whether *part* is a ``load_capability`` call, result, or failed load.

    A skill load reaches the client as a ``skill_loaded`` event, never as tool
    calls: its result is the skill body, which is prompt material for the model,
    not content for the UI or the thread store.
    """
    if isinstance(part, (LoadCapabilityCallPart, LoadCapabilityReturnPart)):
        return True
    return isinstance(part, RetryPromptPart) and part.tool_name == TOOL_LOAD_CAPABILITY


class LoadedSkillTracker:
    """Match ``load_capability`` results to the skills they loaded.

    pydantic-ai names the loaded capability only on the call part, so the tracker
    remembers each call's skill name by tool-call id until its result arrives.
    A call comes before its result both in the event stream and in the run's
    messages, so one tracker serves either walk.
    """

    def __init__(self, skills: Sequence[CopilotSkill]) -> None:
        self._skills_by_name = {skill.name: skill for skill in skills}
        self._skill_names_by_call_id: dict[str, str] = {}

    def observe(self, part: object) -> CopilotSkill | None:
        """Record a load call, or return the skill a successful load loaded.

        Returns ``None`` for any other part, and for a load that did not succeed.
        """
        if isinstance(part, LoadCapabilityCallPart):
            skill_name = str(part.args_as_dict().get("id", ""))
            self._skill_names_by_call_id[part.tool_call_id] = skill_name
            return None
        if isinstance(part, LoadCapabilityReturnPart):
            skill_name = self._skill_names_by_call_id.pop(part.tool_call_id, "")
            if part.outcome != "success":
                return None
            return self._skills_by_name.get(skill_name)
        return None


def register_skill_tools(agent: Agent[CopilotRunContext, str]) -> None:
    """Register the native ``load_skill_reference`` tool on the agent.

    The tool is registered on the agent rather than bundled into each skill's
    capability, so the tool list (and the cached prompt prefix with it) does not
    change when the model loads a skill. It is offered only to runs that have
    skills.
    """

    @agent.tool(
        name=TOOL_LOAD_SKILL_REFERENCE,
        description=_LOAD_SKILL_REFERENCE_DESCRIPTION,
        prepare=_offer_when_run_has_skills,
    )
    async def load_skill_reference(
        ctx: RunContext[CopilotRunContext],
        skill_name: str,
        reference_path: str,
    ) -> str:
        """Return one reference file of a loaded skill, or why it can't be read.

        Args:
            ctx: The run context.
            skill_name: Name of a skill loaded this turn, or given up front.
            reference_path: Path of the reference as the skill gives it.
        """
        return _read_skill_reference(
            ctx.deps.skills, ctx.available_capability_ids, skill_name, reference_path
        )


async def _offer_when_run_has_skills(
    ctx: RunContext[CopilotRunContext], tool_def: ToolDefinition
) -> ToolDefinition | None:
    """Offer the tool only to runs that have Copilot skills."""
    return tool_def if ctx.deps.skills else None


def _read_skill_reference(
    skills: Sequence[CopilotSkill],
    loaded_skill_names: Collection[str],
    skill_name: str,
    reference_path: str,
) -> str:
    """Return the reference's content, or an error the model can act on.

    *loaded_skill_names* are the skills whose body the model has: the deferred
    ones it loaded this run plus any given up front with ``defer_loading=False``.

    Errors are returned as text, not raised as a retry: pydantic-ai ends the run
    once a tool exceeds its retries, and a bad lookup must never do that. Only
    references packaged with the skill can be read, so the path never reaches
    the filesystem.
    """
    skill = next((offered for offered in skills if offered.name == skill_name), None)
    if skill is None:
        names = ", ".join(offered.name for offered in skills)
        return f"There is no skill '{skill_name}' in this session. Skills: {names}."
    if skill_name not in loaded_skill_names:
        return (
            f"Load the skill '{skill_name}' with `{TOOL_LOAD_CAPABILITY}` before "
            "reading its references."
        )
    content = skill.references.get(reference_path)
    if content is None:
        available = ", ".join(skill.references) or "none"
        return (
            f"The skill '{skill_name}' has no reference '{reference_path}'. "
            f"Its references: {available}."
        )
    return content
